// ═════════════════════════ on the way out (never stored) ═════════════════════
const BAR = `<div class="bpd-bar" role="toolbar" aria-label="Print"><button type="button" onclick="window.print()">طباعة / حفظ PDF &nbsp;·&nbsp; Print / Save as PDF</button><span>اختر «حفظ كـ PDF» من نافذة الطباعة · Choose “Save as PDF” as the destination</span></div>
<script>try{if(window.top!==window.self)document.documentElement.classList.add("in-frame")}catch(e){document.documentElement.classList.add("in-frame")}</script>`;

/**
 * Makes a v2 paper ready to be read: hides the company-side DocuSign anchors and
 * adds the print button. Idempotent, and a no-op for anything that is not v2 — so
 * the v1 output that goes through portalContractHtml stays byte-identical.
 */
export function finalizeBpDoc(html) {
  if (!isBpDocV2(html) || html.includes('class="bpd-bar"')) return html;
  const out = html.replace(/\/sig[12]\//g, "").replace(/\/date[12]\//g, "");
  return out.replace(/(<body[^>]*>)/, `$1\n${BAR}`);
}
